CREATE TABLE t1(a,b,c,PRIMARY KEY(a,b,c)) WITHOUT ROWID; INSERT INTO t1 VALUES(1,2,3),(4,5,6); CREATE VIEW v1 AS SELECT a+b AS x,b+c AS y,a+c AS z FROM t1; CREATE TABLE v1log(a,b,c,d,e,f); CREATE TRIGGER r1 INSTEAD OF DELETE ON v1 BEGIN INSERT INTO v1log VALUES(old.x,NULL,old.y,NULL,old.z,NULL); END; CREATE TRIGGER r2 INSTEAD OF INSERT ON v1 BEGIN INSERT INTO v1log VALUES(NULL,new.x,NULL,new.y,NULL,new.z); END;